original_prompt:
앞으로 물어보지 않고 너가 할수 있게 settings.json 변경해줘 {
  "alwaysThinkingEnabled": true,
  "autoSave": true,
  "defaultModel": "claude-opus-4-6",
  "enabledPlugins": {
    "code-review@claude-plugins-official": true,
    "commit-commands@claude-plugins-official": true,
    "security-guidance@claude-plugins-official": true,
    "kotlin-lsp@claude-plugins-official": true,
    "oh-my-claudecode@omc": true,
    "kakaotalk@team-attention-plugins": true
  },
  "env": {
    "BASH_DEFAULT_TIMEOUT_MS": "30000",
    "BASH_MAX_OUTPUT_LENGTH": "50000",
    "BASH_MAX_TIMEOUT_MS": "300000",
    "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS": "1",
    "CLAUDE_CODE_FILE_READ_MAX_OUTPUT_TOKENS": "50000",
    "CLAUDE_CODE_MAX_OUTPUT_TOKENS": "64000",
    "DISABLE_PROMPT_CACHING": "0",
    "MAX_THINKING_TOKENS": "16000"
  },
  "globalShortcut": "CommandOrControl+Shift+Space",
  "hooks": {
    "Stop": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "/Users/seunggabi/.claude/count_tokens.js"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "INPUT=$(cat) && SID=$(echo \"$INPUT\" | jq -r '.session_id // \"unknown\"') && MSG=$(echo \"$INPUT\" | jq -r '.prompt // \"\"' | head -c 200 | sed 's/\"/\\\\\"/g') && mkdir -p .claude/logs && echo '{\"timestamp\":\"'$(date -u +%Y-%m-%dT%H:%M:%S.000Z)'\",\"cwd\":\"'$PWD'\",\"tool\":\"UserPrompt\",\"command\":\"'\"$MSG\"'\",\"status\":\"success\"}' >> .claude/logs/$SID.jsonl"
          }
        ]
      }
    ]
  },
  "ide": "jetbrains",
  "language": "korean",
  "mcpServers": {
    "filesystem": {
      "command": "npx",
      "args": [
        "-y",
        "@modelcontextprotocol/server-filesystem",
        "/Users",
        "/tmp"
      ]
    },
    "git": {
      "command": "npx",
      "args": [
        "-y",
        "@modelcontextprotocol/server-git"
      ]
    }
  },
  "omcHud": {
    "preset": "full",
    "elements": {
      "cwd": true,
      "cwdFormat": "relative",
      "gitRepo": true,
      "gitBranch": true
    }
  },
  "permissions": {
    "defaultMode": "bypassPermissions",
    "deny": [
      "Bash(ssh:*)",
      "Edit(./.env)",
      "Edit(./.env.*)",
      "Read(./**/*.key)",
      "Read(./**/*.pem)",
      "Read(./.env)",
      "Read(./.env.*)",
      "Read(./secrets/**)",
      "Write(./.env)",
      "Write(./.env.*)"
    ]
  },
  "respectGitignore": true,
  "sandbox": {
    "enabled": false
  },
  "skipDangerousModePermissionPrompt": true,
  "statusLine": {
    "type": "command",
    "command": "node /home/seung/.claude/hud/omc-hud.mjs"
  },
  "teams": {
    "enabled": true,
    "maxTeamSize": 10,
    "defaultTimeout": 600000,
    "allowParallelExecution": true,
    "maxConcurrentAgents": 5
  }
} 참고해서 너가 직접 못하면 내가 할수 있게 cli 만들어줘
